use stack::Stack;

#[test]
fn test_new_empty() {
    let s: Stack<i32> = Stack::new();
    assert!(s.is_empty());
    assert_eq!(s.len(), 0);
}

#[test]
fn test_push_and_pop() {
    let mut s = Stack::new();
    s.push(1);
    s.push(2);
    s.push(3);
    assert_eq!(s.pop(), Some(3));
    assert_eq!(s.pop(), Some(2));
    assert_eq!(s.pop(), Some(1));
    assert_eq!(s.pop(), None);
}

#[test]
fn test_peek_does_not_consume() {
    let mut s = Stack::new();
    s.push(42);
    assert_eq!(s.peek(), Some(&42));
    assert_eq!(s.len(), 1);
}

#[test]
fn test_len_after_push_pop() {
    let mut s: Stack<&str> = Stack::new();
    s.push("a");
    s.push("b");
    assert_eq!(s.len(), 2);
    s.pop();
    assert_eq!(s.len(), 1);
    assert!(!s.is_empty());
    s.pop();
    assert!(s.is_empty());
}

#[test]
fn test_peek_empty_returns_none() {
    let s: Stack<u8> = Stack::new();
    assert_eq!(s.peek(), None);
}
